import type { SelectItem } from "@earendil-works/pi-tui";
import type { Snippet } from "./snippets";
import { getSnippetPreview } from "./snippets";

export type SearchIndexItem = {
	item: SelectItem;
	idx: number;
	raw: string;
	normalized: string;
};

export function normalizeForSearch(value: string): string {
	return value
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, " ")
		.replace(/\s+/g, " ")
		.trim();
}

export function buildSearchIndex(snippets: Snippet[], items: SelectItem[]): SearchIndexItem[] {
	return snippets.map((snippet, idx) => {
		const preview = getSnippetPreview(snippet);
		const type = snippet.type;
		const lang = snippet.language ?? "";
		const raw = `${preview} ${type} ${lang} ${snippet.sourceLabel}`.toLowerCase();
		return {
			item: items[idx]!,
			idx,
			raw,
			normalized: normalizeForSearch(raw),
		};
	});
}

export function rankedFilterItems(
	filter: string,
	items: SelectItem[],
	searchIndex: SearchIndexItem[],
): SelectItem[] {
	const lower = filter.toLowerCase();
	if (lower.length === 0) return items;

	const norm = normalizeForSearch(lower);
	const tokens = norm.length > 0 ? norm.split(" ") : [];
	const scored: Array<{ item: SelectItem; idx: number; score: number }> = [];

	for (const entry of searchIndex) {
		let score = 0;

		const rawIndex = entry.raw.indexOf(lower);
		if (rawIndex !== -1) {
			score = 1000 - rawIndex;
		} else if (tokens.length > 0) {
			let allMatch = true;
			let firstPos = Number.MAX_SAFE_INTEGER;
			for (const token of tokens) {
				const pos = entry.normalized.indexOf(token);
				if (pos === -1) {
					allMatch = false;
					break;
				}
				firstPos = Math.min(firstPos, pos);
			}
			if (!allMatch) continue;
			score = 500 - firstPos;
		} else {
			continue;
		}

		scored.push({ item: entry.item, idx: entry.idx, score });
	}

	scored.sort((a, b) => {
		if (b.score !== a.score) return b.score - a.score;
		return a.idx - b.idx;
	});

	return scored.map((entry) => entry.item);
}

export interface FileActionDiffDetails {
  diff: string;
  filePath: string;
  contentText?: string;
  addRowBgMixRatio?: number;
  removeRowBgMixRatio?: number;
}

const FILE_ACTION_CREATE_ADD_BG_MIX_RATIO = 0.16;
const FILE_ACTION_DELETE_REMOVE_BG_MIX_RATIO = 0.08;

function normalizeDiffPath(filePath: string): string {
  return filePath.replace(/\\/g, "/").replace(/^\/+/, "");
}

function normalizeLines(content: string): string[] {
  if (content.length === 0) {
    return [];
  }

  const normalized = content.replace(/\r/g, "");
  const lines = normalized.split("\n");
  if (lines[lines.length - 1] === "") {
    lines.pop();
  }
  return lines;
}

function pluralize(count: number, singular: string): string {
  return count === 1 ? singular : `${singular}s`;
}

function buildCreateSummaryText(lineCount: number): string {
  if (lineCount === 0) {
    return "Created empty file";
  }

  return `Created file • ${lineCount} ${pluralize(lineCount, "line")}`;
}

function buildCreateDiff(filePath: string, content: string): string {
  const normalizedPath = normalizeDiffPath(filePath);
  const lines = normalizeLines(content);
  const diffLines = [`created file ${normalizedPath}`];

  if (lines.length > 0) {
    diffLines.push(`@@ -0,0 +1,${lines.length} @@`);
    diffLines.push(...lines.map((line) => `+${line}`));
  }

  return diffLines.join("\n");
}

function buildDeleteDiff(filePath: string, content: string): string {
  const normalizedPath = normalizeDiffPath(filePath);
  const lines = normalizeLines(content);
  const diffLines = [`deleted file ${normalizedPath}`];

  if (lines.length > 0) {
    diffLines.push(`@@ -1,${lines.length} +0,0 @@`);
    diffLines.push(...lines.map((line) => `-${line}`));
  }

  return diffLines.join("\n");
}

export function normalizeFileActionResult(args: {
  action: unknown;
  path: unknown;
  content: unknown;
  deletedContent?: string;
}): FileActionDiffDetails | null {
  if (typeof args.path !== "string" || args.path.trim().length === 0) {
    return null;
  }

  if (args.action === "create" && typeof args.content === "string") {
    const lineCount = normalizeLines(args.content).length;
    return {
      diff: buildCreateDiff(args.path, args.content),
      filePath: args.path,
      contentText: buildCreateSummaryText(lineCount),
      addRowBgMixRatio: FILE_ACTION_CREATE_ADD_BG_MIX_RATIO,
    };
  }

  if (args.action === "delete" && typeof args.deletedContent === "string") {
    return {
      diff: buildDeleteDiff(args.path, args.deletedContent),
      filePath: args.path,
      removeRowBgMixRatio: FILE_ACTION_DELETE_REMOVE_BG_MIX_RATIO,
    };
  }

  return null;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import type { SessionEntry } from "@earendil-works/pi-coding-agent";

import {
    PORTABILITY_COMMAND_USAGE,
    PORTABILITY_MODE_CUSTOM_TYPE,
    createPortabilityModeRecord,
    isCoordinatorMetadataEntry,
    parsePortabilityCommand,
    parsePortabilityModeRecord,
    resolveSessionPortabilityMode,
} from "./portability-mode.ts";
import {
    LABEL_SENSITIVE_PORTABLE_SUMMARY_CUSTOM_TYPE,
    PORTABLE_SUMMARY_CUSTOM_TYPE,
} from "./portable-record.ts";

function customEntry(id: string, customType: string, data: unknown): SessionEntry {
    return {
        type: "custom",
        id,
        parentId: null,
        timestamp: "2026-07-25T00:00:00.000Z",
        customType,
        data,
    } as SessionEntry;
}

describe("portability mode persistence", () => {
    it("parses and creates only exact v1 records", () => {
        const record = createPortabilityModeRecord("prewarm");
        assert.deepEqual(parsePortabilityModeRecord(record), record);
        for (const value of [
            { ...record, extra: true },
            { ...record, version: 2 },
            { ...record, mode: "fast" },
            Object.assign(Object.create({ kind: PORTABILITY_MODE_CUSTOM_TYPE }), { version: 1, mode: "lazy" }),
        ]) {
            assert.throws(() => parsePortabilityModeRecord(value), /Invalid portability mode record/);
        }
    });

    it("uses the latest session-wide mode entry and permits a later repair", () => {
        const entries = [
            customEntry("mode-1", PORTABILITY_MODE_CUSTOM_TYPE, createPortabilityModeRecord("prewarm")),
            customEntry("branch-fact", "other", {}),
            customEntry("mode-2", PORTABILITY_MODE_CUSTOM_TYPE, createPortabilityModeRecord("lazy")),
        ];
        assert.deepEqual(resolveSessionPortabilityMode(entries), { mode: "lazy", entryId: "mode-2" });
        assert.throws(
            () => resolveSessionPortabilityMode([...entries, customEntry("bad", PORTABILITY_MODE_CUSTOM_TYPE, {})]),
            /bad/,
        );
        assert.deepEqual(resolveSessionPortabilityMode([
            ...entries,
            customEntry("bad", PORTABILITY_MODE_CUSTOM_TYPE, {}),
            customEntry("repair", PORTABILITY_MODE_CUSTOM_TYPE, createPortabilityModeRecord("prewarm")),
        ]), { mode: "prewarm", entryId: "repair" });
    });

    it("defaults sessions without a mode entry to lazy", () => {
        assert.deepEqual(resolveSessionPortabilityMode([]), { mode: "lazy", entryId: null });
    });

    it("accepts only the three exact command arguments", () => {
        assert.equal(parsePortabilityCommand(" prewarm "), "prewarm");
        assert.equal(parsePortabilityCommand("lazy"), "lazy");
        assert.equal(parsePortabilityCommand("status"), "status");
        for (const value of ["", "PREWARM", "prewarm now", "fast"]) {
            assert.throws(() => parsePortabilityCommand(value), new RegExp(PORTABILITY_COMMAND_USAGE.replaceAll("/", "\\/")));
        }
    });

    it("classifies coordinator state and summary records as metadata", () => {
        assert.equal(isCoordinatorMetadataEntry(customEntry("mode", PORTABILITY_MODE_CUSTOM_TYPE, {})), true);
        assert.equal(isCoordinatorMetadataEntry(customEntry("summary", PORTABLE_SUMMARY_CUSTOM_TYPE, {})), true);
        assert.equal(isCoordinatorMetadataEntry(
            customEntry("label-sensitive-summary", LABEL_SENSITIVE_PORTABLE_SUMMARY_CUSTOM_TYPE, {}),
        ), true);
        assert.equal(isCoordinatorMetadataEntry(customEntry("other", "other", {})), false);
    });
});

